
const WORDS=[{"id": 0, "w": "家乡", "p": "jiāxiāng", "t": "名词", "m": "quê nhà, quê hương", "coll": "美丽的家乡、回到家乡", "s": "毕业以后，她回到家乡当了一名老师。"}, {"id": 1, "w": "萝卜", "p": "luóbo", "t": "名词", "m": "cây củ cải, củ cải", "coll": "白萝卜、萝卜饼", "s": "奶奶把萝卜切成细丝，准备做饼。"}, {"id": 2, "w": "怀念", "p": "huáiniàn", "t": "动词", "m": "tưởng nhớ, nhớ", "coll": "怀念童年、十分怀念", "s": "我常常怀念小时候和奶奶一起做饭的日子。"}, {"id": 3, "w": "色彩", "p": "sècǎi", "t": "名词", "m": "màu sắc, sắc thái", "coll": "色彩鲜艳、丰富的色彩", "s": "这幅画色彩鲜艳，让人看了心情愉快。"}, {"id": 4, "w": "想念", "p": "xiǎngniàn", "t": "动词", "m": "nhớ", "coll": "想念家人、非常想念", "s": "离开家乡以后，我特别想念父母。"}, {"id": 5, "w": "青", "p": "qīng", "t": "形容词", "m": "xanh", "coll": "青山、青草", "s": "雨后的山坡上，长满了青青的草。"}, {"id": 6, "w": "紫", "p": "zǐ", "t": "形容词", "m": "tím", "coll": "紫葡萄、紫色", "s": "她买了一条紫色的裙子。"}, {"id": 7, "w": "赏心悦目", "p": "shǎngxīn-yuèmù", "t": "成语", "m": "sướng mắt đẹp lòng", "coll": "令人赏心悦目、赏心悦目的风景", "s": "窗外的花园整齐而美丽，令人赏心悦目。"}, {"id": 8, "w": "般", "p": "bān", "t": "助词", "m": "giống nhau, tựa như", "coll": "梦一般、春天般的温暖", "s": "她的笑容让人感到春天般的温暖。"}, {"id": 9, "w": "清淡", "p": "qīngdàn", "t": "形容词", "m": "nhẹ, dễ tiêu", "coll": "清淡的饭菜、口味清淡", "s": "最近我想吃一些清淡的饭菜。"}, {"id": 10, "w": "可口", "p": "kěkǒu", "t": "形容词", "m": "ngon", "coll": "美味可口、可口的点心", "s": "奶奶做的萝卜饼香甜可口，大家都很喜欢。"}, {"id": 11, "w": "夸", "p": "kuā", "t": "动词", "m": "khen ngợi", "coll": "夸孩子、夸他能干", "s": "老师夸他这次作业写得很认真。"}, {"id": 12, "w": "橘子", "p": "júzi", "t": "名词", "m": "quả quýt", "coll": "剥橘子、一袋橘子", "s": "妈妈买了一袋橘子，让我们带到学校吃。"}, {"id": 13, "w": "梨", "p": "lí", "t": "名词", "m": "quả lê", "coll": "一个梨、削梨皮", "s": "她把一个梨切成小块，放进了盘子里。"}, {"id": 14, "w": "炒", "p": "chǎo", "t": "动词", "m": "xào, rang", "coll": "炒菜、炒鸡蛋", "s": "爸爸正在厨房里炒鸡蛋。"}, {"id": 15, "w": "煮", "p": "zhǔ", "t": "动词", "m": "nấu, đun, luộc", "coll": "煮面、煮熟", "s": "水开以后，再把面条放进去煮。"}, {"id": 16, "w": "油炸", "p": "yóuzhá", "t": "动词", "m": "chiên bằng cách cho nhiều dầu", "coll": "油炸食品、油炸花生", "s": "这道菜需要先经过油炸，再放进锅里炒。"}, {"id": 17, "w": "切", "p": "qiē", "t": "动词", "m": "cắt, xát", "coll": "切菜、切成小块", "s": "请把土豆切成小块，放在盘子里。"}, {"id": 18, "w": "丝", "p": "sī", "t": "名词", "m": "sợi", "coll": "萝卜丝、切成丝", "s": "她把胡萝卜切成丝，准备拌凉菜。"}, {"id": 19, "w": "搅拌", "p": "jiǎobàn", "t": "动词", "m": "khuấy, trộn", "coll": "搅拌均匀、不断搅拌", "s": "把鸡蛋倒进碗里，用筷子搅拌均匀。"}, {"id": 20, "w": "均匀", "p": "jūnyún", "t": "形容词", "m": "đều đặn, đều", "coll": "厚薄均匀、分布均匀", "s": "做饼的时候，要注意让饼的厚薄均匀。"}, {"id": 21, "w": "原料", "p": "yuánliào", "t": "名词", "m": "nguyên liệu", "coll": "准备原料、主要原料", "s": "做这种点心的主要原料是面粉和鸡蛋。"}, {"id": 22, "w": "擀", "p": "gǎn", "t": "动词", "m": "cán, nghiền", "coll": "擀面、擀面皮", "s": "奶奶把面团擀成圆圆的面皮。"}, {"id": 23, "w": "薄", "p": "báo", "t": "形容词", "m": "mỏng", "coll": "薄饼、薄薄的一层", "s": "她把面皮擀得很薄。"}, {"id": 24, "w": "折叠", "p": "zhédié", "t": "动词", "m": "gấp, xếp", "coll": "折叠衣服、折叠整齐", "s": "请把这张纸折叠成三角形。"}, {"id": 25, "w": "透明", "p": "tòumíng", "t": "形容词", "m": "trong suốt", "coll": "透明的玻璃、完全透明", "s": "透过透明的玻璃，我们可以看见厨房里的厨师。"}, {"id": 26, "w": "淋", "p": "lín", "t": "动词", "m": "rải, rưới, đổ vào", "coll": "淋上酱油、淋上少许醋", "s": "吃之前，可以在菜上淋一点儿酱油。"}, {"id": 27, "w": "圈", "p": "quān", "t": "名词", "m": "vòng", "coll": "画一个圈、围成一圈", "s": "孩子们围成一圈，一起做游戏。"}, {"id": 28, "w": "烫", "p": "tàng", "t": "动词／形容词", "m": "làm bỏng, hâm, ủi; nóng", "coll": "很烫、烫伤", "s": "这碗汤还很烫，等一会儿再喝。"}, {"id": 29, "w": "盖", "p": "gài", "t": "动词／名词", "m": "đậy; nắp", "coll": "盖上锅盖、瓶盖", "s": "把锅盖盖好以后，再等五分钟。"}, {"id": 30, "w": "预防", "p": "yùfáng", "t": "动词", "m": "đề phòng, ngăn ngừa", "coll": "预防疾病、提前预防", "s": "养成良好的卫生习惯，有助于预防一些疾病。"}, {"id": 31, "w": "糊", "p": "hú", "t": "动词", "m": "khét, cháy", "coll": "饭糊了、烧糊", "s": "他接电话时忘了关火，结果饭糊了。"}, {"id": 32, "w": "文火", "p": "wénhuǒ", "t": "名词", "m": "lửa nhỏ, lửa riu riu", "coll": "用文火、文火慢煮", "s": "这锅汤需要用文火慢慢煮。"}, {"id": 33, "w": "闻", "p": "wén", "t": "动词", "m": "ngửi", "coll": "闻香味、闻一闻", "s": "刚进厨房，我就闻到了饭菜的香味。"}, {"id": 34, "w": "趁", "p": "chèn", "t": "介词", "m": "nhân (lúc), thừa (dịp)", "coll": "趁热、趁有时间", "s": "饼刚做好，我们趁热吃吧。"}, {"id": 35, "w": "口味", "p": "kǒuwèi", "t": "名词", "m": "mùi vị, hương vị", "coll": "不同口味、适合口味", "s": "这家餐厅的菜很适合我的口味。"}, {"id": 36, "w": "少许", "p": "shǎoxǔ", "t": "形容词", "m": "một chút", "coll": "少许盐、加少许糖", "s": "最后，加入少许盐，再搅拌一下。"}, {"id": 37, "w": "酱油", "p": "jiàngyóu", "t": "名词", "m": "nước tương", "coll": "一瓶酱油、加酱油", "s": "妈妈往菜里加了一点儿酱油。"}, {"id": 38, "w": "醋", "p": "cù", "t": "名词", "m": "giấm", "coll": "一瓶醋、加点儿醋", "s": "吃饺子的时候，我喜欢加一点儿醋。"}, {"id": 39, "w": "焦", "p": "jiāo", "t": "形容词", "m": "bị cháy", "coll": "烤焦、焦了", "s": "面包烤得太久，已经焦了。"}, {"id": 40, "w": "嫩", "p": "nèn", "t": "形容词", "m": "mềm", "coll": "鲜嫩、嫩豆腐", "s": "这盘豆腐又嫩又滑，很好吃。"}, {"id": 41, "w": "特色", "p": "tèsè", "t": "名词", "m": "đặc điểm, đặc trưng", "coll": "地方特色、独具特色", "s": "萝卜饼是这座小城很有特色的一种小吃。"}, {"id": 42, "w": "痰", "p": "tán", "t": "名词", "m": "đờm, dờm", "coll": "咳痰、痰多", "s": "医生询问他咳嗽时有没有痰。"}, {"id": 43, "w": "平安", "p": "píng'ān", "t": "形容词", "m": "bình an, an toàn", "coll": "平安到家、一路平安", "s": "听说你已经平安到家，我们就放心了。"}];
const CHUNKS=[["毕业以后，", "她回到家乡", "当了一名老师。"], ["奶奶", "把萝卜切成细丝，", "准备做饼。"], ["我常常", "怀念小时候", "和奶奶一起做饭的日子。"], ["这幅画", "色彩鲜艳，", "让人看了心情愉快。"], ["离开家乡以后，", "我特别", "想念父母。"], ["雨后的山坡上，", "长满了", "青青的草。"], ["她", "买了一条", "紫色的裙子。"], ["窗外的花园", "整齐而美丽，", "令人赏心悦目。"], ["她的笑容", "让人感到", "春天般的温暖。"], ["最近", "我想吃一些", "清淡的饭菜。"], ["奶奶做的萝卜饼", "香甜可口，", "大家都很喜欢。"], ["老师", "夸他", "这次作业写得很认真。"], ["妈妈", "买了一袋橘子，", "让我们带到学校吃。"], ["她", "把一个梨切成小块，", "放进了盘子里。"], ["爸爸", "正在厨房里", "炒鸡蛋。"], ["水开以后，", "再把面条", "放进去煮。"], ["这道菜", "需要先经过油炸，", "再放进锅里炒。"], ["请", "把土豆切成小块，", "放在盘子里。"], ["她", "把胡萝卜切成丝，", "准备拌凉菜。"], ["把鸡蛋倒进碗里，", "用筷子", "搅拌均匀。"], ["做饼的时候，", "要注意", "让饼的厚薄均匀。"], ["做这种点心的", "主要原料", "是面粉和鸡蛋。"], ["奶奶", "把面团", "擀成圆圆的面皮。"], ["她", "把面皮", "擀得很薄。"], ["请", "把这张纸", "折叠成三角形。"], ["透过透明的玻璃，", "我们可以看见", "厨房里的厨师。"], ["吃之前，", "可以在菜上", "淋一点儿酱油。"], ["孩子们", "围成一圈，", "一起做游戏。"], ["这碗汤", "还很烫，", "等一会儿再喝。"], ["把锅盖", "盖好以后，", "再等五分钟。"], ["养成良好的卫生习惯，", "有助于", "预防一些疾病。"], ["他接电话时", "忘了关火，", "结果饭糊了。"], ["这锅汤", "需要用文火", "慢慢煮。"], ["刚进厨房，", "我就闻到了", "饭菜的香味。"], ["饼刚做好，", "我们", "趁热吃吧。"], ["这家餐厅的菜", "很适合", "我的口味。"], ["最后，", "加入少许盐，", "再搅拌一下。"], ["妈妈", "往菜里", "加了一点儿酱油。"], ["吃饺子的时候，", "我喜欢", "加一点儿醋。"], ["面包", "烤得太久，", "已经焦了。"], ["这盘豆腐", "又嫩又滑，", "很好吃。"], ["萝卜饼", "是这座小城", "很有特色的一种小吃。"], ["医生", "询问他", "咳嗽时有没有痰。"], ["听说你", "已经平安到家，", "我们就放心了。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai19-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===3?WORDS.length:g*10+10);
const groupOf=id=>Math.min(3,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/44 个词语。学完四组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),44)}<div class="ntc-progressgroups">${[0,1,2,3].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共44个词语，点击 ↗ 学习该词语',totalLearned()+'/44 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为四组：10、10、10、14个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===43;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<43){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:3,idx:13};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课44个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课44个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [0, 12, 13], "1": [0, 12, 13], "2": [0, 12, 13], "3": [0, 12, 13], "4": [0, 12, 13], "5": [42, 37, 27], "6": [0, 12, 13], "7": [0, 12, 13], "8": [42, 37, 27], "9": [0, 12, 13], "10": [0, 12, 13], "11": [0, 12, 13], "12": [0, 12, 13], "13": [0, 12, 13], "14": [0, 12, 13], "15": [0, 12, 13], "16": [0, 12, 13], "17": [0, 12, 13], "18": [0, 12, 13], "19": [0, 12, 13], "20": [42, 37, 27], "21": [0, 12, 13], "22": [0, 12, 13], "23": [42, 37, 27], "24": [0, 12, 13], "25": [0, 12, 13], "26": [0, 12, 13], "27": [0, 12, 13], "28": [0, 12, 13], "29": [0, 12, 13], "30": [0, 12, 13], "31": [0, 12, 13], "32": [42, 37, 27], "33": [0, 12, 13], "34": [0, 12, 13], "35": [42, 37, 27], "36": [0, 12, 13], "37": [0, 12, 13], "38": [0, 42, 27], "39": [0, 12, 13], "40": [0, 12, 13], "41": [42, 37, 27], "42": [0, 12, 13], "43": [0, 12, 13]};
const CONFUSABLE={2:[4],4:[2],31:[39],39:[31]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id&&!(CONFUSABLE[id]||[]).includes(d.id)).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的40个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第19课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第19课学习进度','第19课 · 44个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 44</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2,3].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第19课';$('ntc-bookmark').textContent=student?total+'/44 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2,3].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2,3].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第19课学习进度</div><div style="padding:0 10px">'+total+'/44 个已学词语'+meter(total,44)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"家乡":"data:audio/mpeg;base64,","毕业以后，她回到家乡当了一名老师。":"data:audio/mpeg;base64,","萝卜":"data:audio/mpeg;base64,","奶奶把萝卜切成细丝，准备做饼。":"data:audio/mpeg;base64,","怀念":"data:audio/mpeg;base64,","我常常怀念小时候和奶奶一起做饭的日子。":"data:audio/mpeg;base64,","色彩":"data:audio/mpeg;base64,","这幅画色彩鲜艳，让人看了心情愉快。":"data:audio/mpeg;base64,","想念":"data:audio/mpeg;base64,","离开家乡以后，我特别想念父母。":"data:audio/mpeg;base64,","青":"data:audio/mpeg;base64,","雨后的山坡上，长满了青青的草。":"data:audio/mpeg;base64,","紫":"data:audio/mpeg;base64,","她买了一条紫色的裙子。":"data:audio/mpeg;base64,","赏心悦目":"data:audio/mpeg;base64,","窗外的花园整齐而美丽，令人赏心悦目。":"data:audio/mpeg;base64,","般":"data:audio/mpeg;base64,","她的笑容让人感到春天般的温暖。":"data:audio/mpeg;base64,","清淡":"data:audio/mpeg;base64,","最近我想吃一些清淡的饭菜。":"data:audio/mpeg;base64,","可口":"data:audio/mpeg;base64,","奶奶做的萝卜饼香甜可口，大家都很喜欢。":"data:audio/mpeg;base64,","夸":"data:audio/mpeg;base64,","老师夸他这次作业写得很认真。":"data:audio/mpeg;base64,","橘子":"data:audio/mpeg;base64,","妈妈买了一袋橘子，让我们带到学校吃。":"data:audio/mpeg;base64,","梨":"data:audio/mpeg;base64,","她把一个梨切成小块，放进了盘子里。":"data:audio/mpeg;base64,","炒":"data:audio/mpeg;base64,","爸爸正在厨房里炒鸡蛋。":"data:audio/mpeg;base64,","煮":"data:audio/mpeg;base64,","水开以后，再把面条放进去煮。":"data:audio/mpeg;base64,","油炸":"data:audio/mpeg;base64,","这道菜需要先经过油炸，再放进锅里炒。":"data:audio/mpeg;base64,","切":"data:audio/mpeg;base64,","请把土豆切成小块，放在盘子里。":"data:audio/mpeg;base64,","丝":"data:audio/mpeg;base64,","她把胡萝卜切成丝，准备拌凉菜。":"data:audio/mpeg;base64,","搅拌":"data:audio/mpeg;base64,","把鸡蛋倒进碗里，用筷子搅拌均匀。":"data:audio/mpeg;base64,","均匀":"data:audio/mpeg;base64,","做饼的时候，要注意让饼的厚薄均匀。":"data:audio/mpeg;base64,","原料":"data:audio/mpeg;base64,","做这种点心的主要原料是面粉和鸡蛋。":"data:audio/mpeg;base64,","擀":"data:audio/mpeg;base64,","奶奶把面团擀成圆圆的面皮。":"data:audio/mpeg;base64,","薄":"data:audio/mpeg;base64,","她把面皮擀得很薄。":"data:audio/mpeg;base64,","折叠":"data:audio/mpeg;base64,","请把这张纸折叠成三角形。":"data:audio/mpeg;base64,","透明":"data:audio/mpeg;base64,","透过透明的玻璃，我们可以看见厨房里的厨师。":"data:audio/mpeg;base64,","淋":"data:audio/mpeg;base64,","吃之前，可以在菜上淋一点儿酱油。":"data:audio/mpeg;base64,","圈":"data:audio/mpeg;base64,","孩子们围成一圈，一起做游戏。":"data:audio/mpeg;base64,","烫":"data:audio/mpeg;base64,","这碗汤还很烫，等一会儿再喝。":"data:audio/mpeg;base64,","盖":"data:audio/mpeg;base64,","把锅盖盖好以后，再等五分钟。":"data:audio/mpeg;base64,","预防":"data:audio/mpeg;base64,","养成良好的卫生习惯，有助于预防一些疾病。":"data:audio/mpeg;base64,","糊":"data:audio/mpeg;base64,","他接电话时忘了关火，结果饭糊了。":"data:audio/mpeg;base64,","文火":"data:audio/mpeg;base64,","这锅汤需要用文火慢慢煮。":"data:audio/mpeg;base64,","闻":"data:audio/mpeg;base64,","刚进厨房，我就闻到了饭菜的香味。":"data:audio/mpeg;base64,","趁":"data:audio/mpeg;base64,","饼刚做好，我们趁热吃吧。":"data:audio/mpeg;base64,","口味":"data:audio/mpeg;base64,","这家餐厅的菜很适合我的口味。":"data:audio/mpeg;base64,","少许":"data:audio/mpeg;base64,","最后，加入少许盐，再搅拌一下。":"data:audio/mpeg;base64,","酱油":"data:audio/mpeg;base64,","妈妈往菜里加了一点儿酱油。":"data:audio/mpeg;base64,","醋":"data:audio/mpeg;base64,","吃饺子的时候，我喜欢加一点儿醋。":"data:audio/mpeg;base64,","焦":"data:audio/mpeg;base64,","面包烤得太久，已经焦了。":"data:audio/mpeg;base64,","嫩":"data:audio/mpeg;base64,","这盘豆腐又嫩又滑，很好吃。":"data:audio/mpeg;base64,","特色":"data:audio/mpeg;base64,","萝卜饼是这座小城很有特色的一种小吃。":"data:audio/mpeg;base64,","痰":"data:audio/mpeg;base64,","医生询问他咳嗽时有没有痰。":"data:audio/mpeg;base64,","平安":"data:audio/mpeg;base64,","听说你已经平安到家，我们就放心了。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai19-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai19_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai19-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=44)||!p.memory)throw Error();if(!confirm('恢复第19课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<44;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<4&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<44&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第19课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

